const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const cities = {
    'Beijing': ee.Geometry.Point(116.4074, 39.9042).buffer(10000), // 10km buffer
    'Chongqing': ee.Geometry.Point(106.5045, 29.5332).buffer(10000), // 10km buffer
    'Wuhan': ee.Geometry.Point(114.3055, 30.5928).buffer(10000) // 10km buffer
  };

  const dateP1_start = '2020-01-01';
  const dateP1_end = '2020-01-20';
  const dateP2_start = '2020-02-10';
  const dateP2_end = '2020-02-25';

  const no2Band = 'tropospheric_NO2_column_number_density';
  const scale = 1000; // Resolution for reduceRegion, S5P native resolution is ~5.5km x 3.5km

  let allCitiesDecreased = true;
  const results = {};

  for (const cityName in cities) {
    const cityGeom = cities[cityName];

    // Function to filter and process NO2 data
    const getNO2 = (startDate, endDate, geometry) => {
      let collection = ee.ImageCollection('COPERNICUS/S5P/OFFLINE/L3_NO2')
        .filterDate(startDate, endDate)
        .filterBounds(geometry)
        .select([no2Band, 'qa_value'])
        .filter(ee.Filter.gte('qa_value', 0.75)); // Filter for good quality pixels

      if (collection.size().getInfo() === 0) {
        throw new Error(`C1: No S5P images found for ${cityName} during ${startDate}-${endDate}.`);
      }

      // Compute the mean image for the period
      const meanImage = collection.mean();

      if (!meanImage) {
        throw new Error(`C3: Mean image computation failed for ${cityName} during ${startDate}-${endDate}.`);
      }

      // Reduce region to get mean NO2 value and pixel count
      const reduction = meanImage.reduceRegion({
        reducer: ee.Reducer.mean().combine({
          reducer2: ee.Reducer.count(),
          sharedInputs: true
        }),
        geometry: geometry,
        scale: scale,
        maxPixels: 1e9
      });

      const meanNO2 = reduction.get(no2Band).getInfo();
      const pixelCount = reduction.get(no2Band + '_count').getInfo();

      if (pixelCount === null || pixelCount === 0) {
        throw new Error(`C2: No valid pixels for ${cityName} after cloud masking/processing during ${startDate}-${endDate}.`);
      }
      if (meanNO2 === null || isNaN(meanNO2)) {
        throw new Error(`C3: Mean NO2 calculation failed for ${cityName} during ${startDate}-${endDate}. Result is None/NaN.`);
      }

      return {
        meanNO2: meanNO2,
        pixelCount: pixelCount,
        imageCount: collection.size().getInfo()
      };
    };

    try {
      // Period 1
      const p1Data = await getNO2(dateP1_start, dateP1_end, cityGeom);
      results[`${cityName}_P1`] = p1Data;

      // Period 2
      const p2Data = await getNO2(dateP2_start, dateP2_end, cityGeom);
      results[`${cityName}_P2`] = p2Data;

      console.log(`${cityName} P1 (${dateP1_start}-${dateP1_end}): Images: ${p1Data.imageCount}, Pixels: ${p1Data.pixelCount}, NO2: ${p1Data.meanNO2.toFixed(8)}`);
      console.log(`${cityName} P2 (${dateP2_start}-${dateP2_end}): Images: ${p2Data.imageCount}, Pixels: ${p2Data.pixelCount}, NO2: ${p2Data.meanNO2.toFixed(8)}`);

      if (p2Data.meanNO2 >= p1Data.meanNO2) {
        allCitiesDecreased = false;
        console.log(`  -> NO2 did NOT decrease in ${cityName}.`);
      } else {
        console.log(`  -> NO2 decreased in ${cityName}.`);
      }

    } catch (e) {
      if (e.message.startsWith('C1:')) {
        console.log(e.message);
        console.log("C1");
        return;
      } else if (e.message.startsWith('C2:')) {
        console.log(e.message);
        console.log("C2");
        return;
      } else if (e.message.startsWith('C3:')) {
        console.log(e.message);
        console.log("C3");
        return;
      } else {
        console.log(`D: An unexpected error occurred: ${e.message}`);
        return;
      }
    }
  }

  if (allCitiesDecreased) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
